/*
 * sparseconfig.h for building against sparsehash 2.0.4 headers with MSVC 2022 (hub-owned build config,
 * not part of torchsparse or sparsehash). Put its folder on the include path BEFORE sparsehash's src/.
 *
 * On Linux this file is generated by sparsehash's ./configure; with a modern C++ standard library it
 * selects std::hash from <functional>, which is what this file does. sparsehash's own
 * src/windows/sparsehash/internal/sparseconfig.h selects stdext::hash_compare, which MSVC's STL no
 * longer provides (VS 2022 17.14: "'hash_compare': is not a member of 'stdext'").
 */
#define GOOGLE_NAMESPACE ::google
#define HASH_FUN_H <functional>
#define HASH_NAMESPACE std
#define HAVE_INTTYPES_H 1
#define HAVE_LONG_LONG 1
#define HAVE_MEMCPY 1
#define HAVE_STDINT_H 1
#define HAVE_SYS_TYPES_H 1
#define HAVE_UINT16_T 1
#undef HAVE_U_INT16_T
#undef HAVE___UINT16
#define SPARSEHASH_HASH HASH_NAMESPACE::hash
#define SPARSEHASH_HASH_NO_NAMESPACE hash
#define _END_GOOGLE_NAMESPACE_ }
#define _START_GOOGLE_NAMESPACE_ namespace google {
